    out = [row[:] for row in grid]
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    background = max(colors, key=colors.get)
    marker = next((v for v in colors if v != background), None)
    if marker is None:
        return out
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == marker]
        for a, b in zip(cols, cols[1:]):
